<script setup lang="ts">
import { onUnmounted, ref, watch } from "vue";
import { useAuth } from "@papilio/auth";
import { item, request, query, type Page, type PaymentDestination, type SmsReceivingRealm, type SmsReceivingAlias, type SmsOriginCapabilities } from "@papilio/api";
import { faNumber } from "@papilio/ui";
import { useI18n } from "vue-i18n";
import Modal from "@papilio/ui/Modal.vue";
const props=defineProps<{destination:PaymentDestination|null;capabilities:SmsOriginCapabilities|null}>();
const open=defineModel<boolean>({required:true});const emit=defineEmits<{saved:[destination:PaymentDestination]}>();
const auth=useAuth(),{t}=useI18n(),base="/v1/admin/payments/sms-origins";
const current=ref<PaymentDestination|null>(null),realm=ref<SmsReceivingRealm|null>(null),alias=ref<SmsReceivingAlias|null>(null),rows=ref<SmsReceivingRealm[]>([]),page=ref(1),pages=ref(1),q=ref(""),namespace=ref(""),error=ref(""),busy=ref(false),loading=ref(false),fresh=ref<{destination:PaymentDestination;realm:SmsReceivingRealm}|null>(null);
let alive=true,sequence=0,loadSequence=0;
function message(cause:unknown):string{return cause instanceof Error?cause.message:t("paymentBinding.operationFailed");}
async function load():Promise<void>{const key=++loadSequence;loading.value=true;try{const result=await request<Page<SmsReceivingRealm>>(`${base}/receiving-realms?${query({page:page.value,q:q.value})}`);if(!alive||key!==loadSequence)return;rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;}catch(cause){if(alive&&key===loadSequence)error.value=message(cause);}finally{if(alive&&key===loadSequence)loading.value=false;}}
async function initialize():Promise<void>{const selected=props.destination;if(!selected)return;if(current.value?.destination_id===selected.destination_id)return;const key=++sequence;current.value=selected;realm.value=null;alias.value=null;fresh.value=null;namespace.value="";error.value="";busy.value=true;try{const destination=await item<PaymentDestination>(`/v1/admin/payments/destinations/${selected.destination_id}`);if(!alive||key!==sequence)return;current.value=destination;if(destination.receiving_alias_id!=null){const bound=await item<SmsReceivingAlias>(`${base}/aliases/${destination.receiving_alias_id}`);const account=await item<SmsReceivingRealm>(`${base}/receiving-realms/${bound.realm_id}`);if(!alive||key!==sequence)return;alias.value=bound;realm.value=account;namespace.value=bound.bank_namespace??"";}await load();}catch(cause){if(alive&&key===sequence)error.value=message(cause);}finally{if(alive&&key===sequence)busy.value=false;}}
function choose(row:SmsReceivingRealm):void{if(busy.value)return;realm.value=row;fresh.value=null;}
async function refresh():Promise<void>{if(!current.value||!realm.value||busy.value)return;busy.value=true;error.value="";try{const destination=await item<PaymentDestination>(`/v1/admin/payments/destinations/${current.value.destination_id}`);const account=await item<SmsReceivingRealm>(`${base}/receiving-realms/${realm.value.id}`);if(alive)fresh.value={destination,realm:account};}catch(cause){if(alive)error.value=message(cause);}finally{if(alive)busy.value=false;}}
function adopt():void{if(!fresh.value||busy.value)return;current.value=fresh.value.destination;realm.value=fresh.value.realm;fresh.value=null;}
async function save():Promise<void>{const destination=current.value,account=realm.value;if(!destination||!account||destination.revision==null||busy.value||!auth.can("payments","update")||!props.capabilities?.enabled)return;busy.value=true;error.value="";try{const result=await item<PaymentDestination>(`${base}/destinations/${destination.destination_id}/receiving-account`,"PUT",{realm_id:account.id,expected_destination_revision:destination.revision,expected_realm_revision:account.revision,bank_namespace:destination.kind==='bank_account'?namespace.value.trim()||null:null});if(!alive)return;current.value=result;emit("saved",result);open.value=false;}catch(cause){if(alive)error.value=message(cause);}finally{if(alive)busy.value=false;}}
watch(()=>[open.value,props.destination?.destination_id],()=>{if(open.value)void initialize();},{immediate:true});onUnmounted(()=>{alive=false;++sequence;++loadSequence;});
</script>
<template><Modal v-model="open" :title="t('paymentBinding.title')" :busy="busy" wide><p v-if="error" class="message error" role="alert">{{error}}</p><template v-if="current"><h3>{{current.title}}</h3><p>{{t('paymentBinding.destinationId',{id:faNumber(current.destination_id)})}} · {{t('paymentBinding.savedRevision',{revision:faNumber(current.revision??0)})}}</p><p class="hint-box">{{t('paymentBinding.description')}}</p><p v-if="alias">{{t('paymentBinding.existingAlias',{id:faNumber(alias.id),kind:alias.kind})}} · {{t('paymentBinding.identity')}} <code>{{alias.account_sha256}}</code></p><p v-if="realm">{{t('paymentBinding.selectedAccount')}}: <strong>{{realm.title}}</strong> · #{{faNumber(realm.id)}} · {{t('paymentBinding.revision',{revision:faNumber(realm.revision)})}}</p><form class="toolbar" @submit.prevent="page=1;load()"><label class="field"><span>{{t('paymentBinding.find')}}</span><input v-model="q" :disabled="busy"/></label><button class="btn secondary" :disabled="busy||loading">{{t('paymentBinding.search')}}</button></form><p v-if="loading">{{t('paymentBinding.loading')}}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>{{t('paymentBinding.account')}}</th><th>{{t('paymentBinding.status')}}</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.title}}</td><td>{{row.is_active?t('paymentBinding.enabled'):t('paymentBinding.disabled')}}</td><td><button type="button" class="btn small secondary" :disabled="busy||!row.is_active" @click="choose(row)">{{realm?.id===row.id?t('paymentBinding.selected'):t('paymentBinding.select')}}</button></td></tr></tbody></table></div><p v-if="!loading&&!rows.length">{{t('paymentBinding.empty')}}</p><div class="pager"><button :disabled="busy||loading||page<=1" :aria-label="t('paymentBinding.previousPage')" @click="page--;load()">‹</button><span>{{faNumber(page)}} / {{faNumber(pages)}}</span><button :disabled="busy||loading||page>=pages" :aria-label="t('paymentBinding.nextPage')" @click="page++;load()">›</button></div><label v-if="current.kind==='bank_account'" class="field"><span>{{t('paymentBinding.namespace')}}</span><input v-model="namespace" required maxlength="100" :disabled="busy"/><small>{{t('paymentBinding.namespaceHint')}}</small></label><div class="inline-actions"><button class="btn secondary" :disabled="busy||!realm" @click="refresh">{{t('paymentBinding.refreshRetain')}}</button><button class="btn" :disabled="busy||!realm||!realm.is_active||current.revision==null||!capabilities?.enabled||!auth.can('payments','update')||current.kind==='bank_account'&&!namespace.trim()" @click="save">{{t('paymentBinding.bind')}}</button></div><section v-if="fresh" class="hint-box"><p>{{t('paymentBinding.currentRecords',{destination:fresh.destination.title,kind:fresh.destination.kind,destinationRevision:faNumber(fresh.destination.revision??0),account:fresh.realm.title,accountRevision:faNumber(fresh.realm.revision)})}}</p><button class="btn secondary" :disabled="busy" @click="adopt">{{t('paymentBinding.adopt')}}</button></section></template></Modal></template>
<style scoped>code{overflow-wrap:anywhere}</style>
